        emon.Testport.AssertEqAt(emon.Port.CellsAt(cs, nx - 2), 69, "E", line);
        emon.Testport.AssertEqAt(emon.Port.CellsAt(cs, nx - 1), 73, "I", line);
        emon.Testport.AssertThatAt(Pdfimage.PiGet(im, Pdfimage.PiFDstart()) < Pdfimage.PiGet(im, Pdfimage.PiFDend()), "the data is not empty", line);
        emon.Testport.AssertThatAt(Pdfimage.PiGet(im, Pdfimage.PiFDend()) <= (nx - 2), "the data ends at or before the EI", line);
        return 0;
    }
    internal static int ItDoc(emon.Port.Src src, emon.Port.Cells ar, emon.Port.Cells dc, emon.Port.Cells a, emon.Port.Cells b, emon.Port.Cells st, emon.Port.Cells cx, emon.Port.Cells ox, emon.Port.Cells cs, emon.Port.Cells @out, emon.Port.Cells f0, emon.Port.Cells f1, emon.Port.Cells f2, emon.Port.Cells f3, emon.Port.Cells gl, emon.Port.Cells et, emon.Port.Cells mk, emon.Port.Cells fnt, emon.Port.Cells pg, emon.Port.Cells wd, emon.Port.Cells ln, emon.Port.Cells pa, emon.Port.Cells im, emon.Port.Cells pts, emon.Port.Cells gx) {
        int o = Pdfdoc.PdOpen(src, ar, dc, a, b, st);
        if (o != 0) {
            return 100 + o;
        }
        return Pdfcontent.PcDocument(src, ar, dc, a, b, st, cx, ox, cs, @out, f0, f1, f2, f3, gl, et, mk, fnt, pg, wd, ln, pa, im, pts, gx);
    }
    internal static int ItM(int emonT, byte[] rows, int pos, int e, int line) {
        // M name file n obj,x0,y0,x1,y1,skewed ... : the placements, in the order the content draws them
        emon.Port.Cells ar = emon.Port.NewCells();
        emon.Port.Cells dc = emon.Port.NewCells();
        emon.Port.Cells a = emon.Port.NewCells();
        emon.Port.Cells b = emon.Port.NewCells();
        emon.Port.Cells st = emon.Port.NewCells();
        emon.Port.Cells cx = emon.Port.NewCells();
        emon.Port.Cells ox = emon.Port.NewCells();
        emon.Port.Cells cs = emon.Port.NewCells();
        emon.Port.Cells @out = emon.Port.NewCells();
        emon.Port.Cells f0 = emon.Port.NewCells();
        emon.Port.Cells f1 = emon.Port.NewCells();
        emon.Port.Cells f2 = emon.Port.NewCells();
        emon.Port.Cells f3 = emon.Port.NewCells();
        emon.Port.Cells gl = emon.Port.NewCells();
        emon.Port.Cells et = emon.Port.NewCells();
        emon.Port.Cells mk = emon.Port.NewCells();
        emon.Port.Cells fnt = emon.Port.NewCells();
        emon.Port.Cells pg = emon.Port.NewCells();
        emon.Port.Cells wd = emon.Port.NewCells();
        emon.Port.Cells ln = emon.Port.NewCells();
        emon.Port.Cells pa = emon.Port.NewCells();
        emon.Port.Cells im = emon.Port.NewCells();
        emon.Port.Cells pts = emon.Port.NewCells();
        emon.Port.Cells gx = emon.Port.NewCells();
        int fs = ItStart(rows, pos, e, 2);
        int fe = ItEnd(rows, fs, e);
        int n = ItInt(rows, pos, e, 3);
        int k = 0;
        int p = 0;
        int q = 0;
        emon.Testport.AssertEqAt(ItDoc(emon.Port.SrcOfBlob(emon.Testport.TestFileSpan(rows, fs, fe)), ar, dc, a, b, st, cx, ox, cs, @out, f0, f1, f2, f3, gl, et, mk, fnt, pg, wd, ln, pa, im, pts, gx), 0, "the page runs", line);
        emon.Testport.AssertEqAt(Evidence.ImCount(im), n, "the number of placements", line);
        if (Evidence.ImCount(im) == n) {
            while (k < n) {
                p = ItStart(rows, pos, e, 4 + k);
                q = ItEnd(rows, p, e);
                emon.Testport.AssertEqAt(Evidence.ImGet(im, k, Evidence.MfObj()), ItCint(rows, p, q, 0), "the image object", line);
                emon.Testport.AssertEqAt(Evidence.ImGet(im, k, Evidence.MfX0()), ItCint(rows, p, q, 1), "x0 in page space", line);
                emon.Testport.AssertEqAt(Evidence.ImGet(im, k, Evidence.MfY0()), ItCint(rows, p, q, 2), "y0 in page space", line);
                emon.Testport.AssertEqAt(Evidence.ImGet(im, k, Evidence.MfX1()), ItCint(rows, p, q, 3), "x1 in page space", line);
                emon.Testport.AssertEqAt(Evidence.ImGet(im, k, Evidence.MfY1()), ItCint(rows, p, q, 4), "y1 in page space", line);
                emon.Testport.AssertEqAt(Evidence.ImGet(im, k, Evidence.MfSkewed()), ItCint(rows, p, q, 5), "skewed", line);
                k += 1;
            }
        }
        return 0;
    }
    internal static int ItRows(int emonT, byte[] rows) {
        // Check every row; answers how many were checked.
        int n = emon.Port.BlobLen(rows);
        int pos = 0;
        int line = 0;
        int e = 0;
        int kind = 0;
        int @checked = 0;
        while (pos < n) {
            line += 1;
            e = ItNl(rows, pos);
            if ((pos < e) && (emon.Port.BlobU8(rows, pos) != 35)) {
                kind = emon.Port.BlobU8(rows, pos);
                @checked += 1;
                if (kind == 68) {
                    ItD(emonT, rows, pos, e, line);
                }
                if (kind == 80) {
                    ItP(emonT, rows, pos, e, line);
                }
                if (kind == 82) {
                    ItR(emonT, rows, pos, e, line);
                }
                if (kind == 79) {
                    ItO(emonT, rows, pos, e, line);
                }
                if (kind == 88) {
                    ItX(emonT, rows, pos, e, line);
                }
                if (kind == 73) {
                    ItI(emonT, rows, pos, e, line);
                }
                if (kind == 77) {
                    ItM(emonT, rows, pos, e, line);
                }
            }
            pos = e + 1;
        }
        return @checked;
    }
