    internal static int ItHexCells(byte[] b, emon.Port.Cells c) {
        // The bytes of a `hex-blob` as one cell each.
        int i = 0;
        emon.Port.CellsDrop(c, 0);
        while (i < emon.Port.BlobLen(b)) {
            emon.Port.CellsPush(c, emon.Port.BlobU8(b, i));
            i += 1;
        }
        return 0;
    }
    internal static int ItVerdict(int emonT, emon.Port.Cells im, emon.Port.Cells data, byte[] hex, int want, int line) {
        // `pi-passthrough` of a hand-made JPEG (the record is a 24 x 16 DeviceRGB DCT image's).
        ItHexCells(hex, data);
        emon.Testport.AssertEqAt(Pdfimage.PiPassthrough(im, data), want, "the verdict of the marker walk", line);
        return 0;
    }
    [Xunit.Fact]
    public static void TestTheMarkerWalkDecidesPassthrough() {
        emon.Port.Cells ar = emon.Port.NewCells();
        emon.Port.Cells dc = emon.Port.NewCells();
        emon.Port.Cells a = emon.Port.NewCells();
        emon.Port.Cells b = emon.Port.NewCells();
        emon.Port.Cells st = emon.Port.NewCells();
        emon.Port.Cells @out = emon.Port.NewCells();
        emon.Port.Cells im = emon.Port.NewCells();
        emon.Port.Cells data = emon.Port.NewCells();
        int sh = 0;
        emon.Port.Src src = emon.Port.SrcOfBlob(emon.Testport.TestFile("assets/dct-rgb.pdf"));
        emon.Testport.AssertEq(Pdfdoc.PdOpen(src, ar, dc, a, b, st), 0, "the file opens");
        sh = Pdfdoc.PdGet(src, ar, dc, a, b, st, 5);
        emon.Testport.AssertEq(Pdfimage.PiInfo(src, ar, dc, a, b, st, @out, im, sh, 5), 0, "the image is read");
        // baseline, progressive, with fill bytes before the marker
        ItVerdict(0, im, data, emon.Testport.HexBlob("ffd8ffc00011080010001803011100021101031101ffd9"), 0, 1);
        ItVerdict(0, im, data, emon.Testport.HexBlob("ffd8ffc20011080010001803011100021101031101ffd9"), 0, 2);
        ItVerdict(0, im, data, emon.Testport.HexBlob("ffd8ffffffc00011080010001803011100021101031101ffd9"), 0, 3);
        // lossless and hierarchical: SOF3, SOF5, SOF7 (reason 5); arithmetic: SOF9, SOF10, SOF11, SOF13, SOF15 (reason 4)
        ItVerdict(0, im, data, emon.Testport.HexBlob("ffd8ffc30011080010001803011100021101031101ffd9"), 5, 4);
        ItVerdict(0, im, data, emon.Testport.HexBlob("ffd8ffc50011080010001803011100021101031101ffd9"), 5, 5);
        ItVerdict(0, im, data, emon.Testport.HexBlob("ffd8ffc70011080010001803011100021101031101ffd9"), 5, 6);
        ItVerdict(0, im, data, emon.Testport.HexBlob("ffd8ffc90011080010001803011100021101031101ffd9"), 4, 7);
        ItVerdict(0, im, data, emon.Testport.HexBlob("ffd8ffca0011080010001803011100021101031101ffd9"), 4, 8);
        ItVerdict(0, im, data, emon.Testport.HexBlob("ffd8ffcb0011080010001803011100021101031101ffd9"), 4, 9);
        ItVerdict(0, im, data, emon.Testport.HexBlob("ffd8ffcd0011080010001803011100021101031101ffd9"), 4, 10);
        ItVerdict(0, im, data, emon.Testport.HexBlob("ffd8ffcf0011080010001803011100021101031101ffd9"), 4, 11);
        // components: 2 and 4 are not 1 or 3, and 1 is not DeviceRGB's; precision 12; a size that is not the dictionary's
        ItVerdict(0, im, data, emon.Testport.HexBlob("ffd8ffc0000e080010001802011100021101ffd9"), 6, 12);
        ItVerdict(0, im, data, emon.Testport.HexBlob("ffd8ffc00014080010001804011100021101031101041101ffd9"), 6, 13);
        ItVerdict(0, im, data, emon.Testport.HexBlob("ffd8ffc0000b080010001801011100ffd9"), 6, 14);
        ItVerdict(0, im, data, emon.Testport.HexBlob("ffd8ffc000110c0010001803011100021101031101ffd9"), 7, 15);
        ItVerdict(0, im, data, emon.Testport.HexBlob("ffd8ffc00011080010001903011100021101031101ffd9"), 15, 16);
        ItVerdict(0, im, data, emon.Testport.HexBlob("ffd8ffc00011080011001803011100021101031101ffd9"), 15, 17);
        // no SOF, no SOI, a segment longer than the data, a stray byte where a marker belongs
        ItVerdict(0, im, data, emon.Testport.HexBlob("ffd8ffd9"), 3, 18);
        ItVerdict(0, im, data, emon.Testport.HexBlob("0000ffc00011080010001803011100021101031101ffd9"), 3, 19);
        ItVerdict(0, im, data, emon.Testport.HexBlob("ffd8ffc00011"), 3, 20);
        ItVerdict(0, im, data, emon.Testport.HexBlob("ffd8ffc000ff0800100018"), 3, 21);
        ItVerdict(0, im, data, emon.Testport.HexBlob("ffd800ffffc00011080010001803011100021101031101ffd9"), 3, 22);
        // Exif orientation: 6 turns it (little and big endian), 1 does not, and an APP1 that is not Exif is not read
        ItVerdict(0, im, data, emon.Testport.HexBlob("ffd8ffe1002245786966000049492a0008000000010012010300010000000600000000000000ffc00011080010001803011100021101031101ffd9"), 14, 23);
        ItVerdict(0, im, data, emon.Testport.HexBlob("ffd8ffe100224578696600004d4d002a00000008000101120003000000010006000000000000ffc00011080010001803011100021101031101ffd9"), 14, 24);
        ItVerdict(0, im, data, emon.Testport.HexBlob("ffd8ffe1002245786966000049492a0008000000010012010300010000000100000000000000ffc00011080010001803011100021101031101ffd9"), 0, 25);
        ItVerdict(0, im, data, emon.Testport.HexBlob("ffd8ffe100224578696600004d4d002a00000008000101120003000000010001000000000000ffc00011080010001803011100021101031101ffd9"), 0, 26);
        ItVerdict(0, im, data, emon.Testport.HexBlob("ffd8ffe10008787878787878ffc00011080010001803011100021101031101ffd9"), 0, 27);
    }
    [Xunit.Fact]
    public static void TestThePassthroughConditionsOfTheDictionary() {
        // A JPEG that would pass, in an image whose dictionary says otherwise: /Decode, a mask, /ImageMask, an Indexed
        // or CMYK colour space, a filter after DCT, and a bit depth that is not 8 are each their own reason.
        emon.Port.Cells ar = emon.Port.NewCells();
        emon.Port.Cells dc = emon.Port.NewCells();
        emon.Port.Cells a = emon.Port.NewCells();
        emon.Port.Cells b = emon.Port.NewCells();
        emon.Port.Cells st = emon.Port.NewCells();
        emon.Port.Cells @out = emon.Port.NewCells();
        emon.Port.Cells im = emon.Port.NewCells();
        emon.Port.Cells data = emon.Port.NewCells();
        int sh = 0;
        emon.Port.Src src = emon.Port.SrcOfBlob(emon.Testport.TestFile("assets/dct-decode.pdf"));
        emon.Testport.AssertEq(Pdfdoc.PdOpen(src, ar, dc, a, b, st), 0, "the file opens");
        sh = Pdfdoc.PdGet(src, ar, dc, a, b, st, 5);
        emon.Testport.AssertEq(Pdfimage.PiInfo(src, ar, dc, a, b, st, @out, im, sh, 5), 0, "the image is read");
        ItHexCells(emon.Testport.HexBlob("ffd8ffc00011080010001803011100021101031101ffd9"), data);
        emon.Testport.AssertEq(Pdfimage.PiPassthrough(im, data), 10, "a /Decode that is not the default is reason 10");
        emon.Testport.AssertEq(Pdfimage.PiGet(im, Pdfimage.PiFClass()), 2, "the colour class is RGB");
        emon.Testport.AssertEq(Pdfimage.PiGet(im, Pdfimage.PiFCodec()), 7, "DCTDecode ends the chain");
    }
